// Prerequisites: Setup bpmn-js project as per SETUP.md
// 1. Start the Camunda Modeler or a bpmn-js demo app
// 2. Create a process with a task and a boundary event with a label (vertically aligned)
// 3. Copy the boundary event (with label)
// 4. Paste it onto a vertical flow (sequence flow with vertical direction)
// 5. Observe the label position after pasting

// Example code for a test (pseudo-code, for bpmn-js test suite):
import BpmnModeler from 'bpmn-js/lib/Modeler';
import diagramXML from './diagram.bpmn'; // diagram with a task and boundary event

const modeler = new BpmnModeler({
  container: '#canvas'
});

modeler.importXML(diagramXML, function(err) {
  if (err) {
    console.error('Failed to import diagram', err);
    return;
  }
  // Simulate user action: select boundary event
  const elementRegistry = modeler.get('elementRegistry');
  const boundaryEvent = elementRegistry.get('BoundaryEvent_1');
  modeler.get('selection').select(boundaryEvent);

  // Simulate copy
  modeler.get('copyPaste').copy([ boundaryEvent ]);

  // Simulate paste on a vertical flow
  const verticalFlow = elementRegistry.get('SequenceFlow_1');
  modeler.get('copyPaste').paste({ element: verticalFlow });

  // Check label position
  // (In real test, assert label position is adapted. In bug, it is not.)
});
